from pathlib import Pathfrom uuid import uuid5, NAMESPACE_URLimport argparseimport refrom qdrant_client import QdrantClientfrom qdrant_client.models import (    Distance,    VectorParams,    PointStruct,)from sentence_transformers import SentenceTransformerMODEL_PATH = "models/bge-m3"COLLECTION = "documents"QDRANT_URL = "http://localhost:6333"CHUNK_SIZE = 1200OVERLAP = 200def get_document_name(markdown_path: Path) -> str:    """    Акт №87 от 31.03.20_0.md    ->    Акт №87 от 31.03.20    """    name = markdown_path.stem    # PaddleOCR добавляет номер страницы _0, _1...    name = re.sub(r"_\d+$", "", name)    return namedef split_markdown(    text: str,    chunk_size: int = CHUNK_SIZE,    overlap: int = OVERLAP,):    blocks = re.split(        r"\n(?=#{1,6}\s|\|)",        text,    )    chunks = []    for block in blocks:        block = block.strip()        if not block:            continue        if len(block) <= chunk_size:            chunks.append(block)            continue        start = 0        while start < len(block):            end = min(                start + chunk_size,                len(block),            )            chunk = block[start:end].strip()            if chunk:                chunks.append(chunk)            if end >= len(block):                break            start = end - overlap    return chunksdef main():    parser = argparse.ArgumentParser()    parser.add_argument(        "markdown",        help="Путь к Markdown-файлу после OCR",    )    args = parser.parse_args()    markdown_path = Path(args.markdown)    if not markdown_path.exists():        raise FileNotFoundError(            f"Файл не найден: {markdown_path}"        )    document_name = get_document_name(        markdown_path    )    print(f"Файл: {markdown_path}")    print(f"Документ: {document_name}")    # ------------------------------------------------------    # Markdown    # ------------------------------------------------------    markdown = markdown_path.read_text(        encoding="utf-8"    )    chunks = split_markdown(        markdown    )    print(        f"Создано chunks: {len(chunks)}"    )    # ------------------------------------------------------    # BGE-M3    # ------------------------------------------------------    print("Загружаю BGE-M3...")    model = SentenceTransformer(        MODEL_PATH,        local_files_only=True,    )    vector_size = (        model.get_sentence_embedding_dimension()    )    print(        f"Размер embedding: {vector_size}"    )    # Добавляем имя документа в embedding.    embedding_texts = [        f"Документ: {document_name}\n\n{chunk}"        for chunk in chunks    ]    print("Создаю embeddings...")    vectors = model.encode(        embedding_texts,        normalize_embeddings=True,        show_progress_bar=True,    )    # ------------------------------------------------------    # Qdrant    # ------------------------------------------------------    client = QdrantClient(        url=QDRANT_URL    )    # ВАЖНО:    # коллекцию больше НЕ удаляем.    if not client.collection_exists(        COLLECTION    ):        print(            f"Создаю коллекцию {COLLECTION}"        )        client.create_collection(            collection_name=COLLECTION,            vectors_config=VectorParams(                size=vector_size,                distance=Distance.COSINE,            ),        )    # ------------------------------------------------------    # Points    # ------------------------------------------------------    points = []    for index, (chunk, vector) in enumerate(        zip(chunks, vectors)    ):        # Стабильный UUID.        # Повторная индексация того же chunk        # перезапишет существующую точку.        point_id = str(            uuid5(                NAMESPACE_URL,                f"{document_name}:{index}",            )        )        points.append(            PointStruct(                id=point_id,                vector=vector.tolist(),                payload={                    "document": document_name,                    "chunk_index": index,                    "text": chunk,                },            )        )    print(        f"Записываю {len(points)} "        f"chunks в Qdrant..."    )    client.upsert(        collection_name=COLLECTION,        points=points,        wait=True,    )    print()    print("Индексация завершена")    print(        f"Документ: {document_name}"    )    print(        f"Chunks: {len(chunks)}"    )    info = client.get_collection(        COLLECTION    )    print(        f"Всего points в Qdrant: "        f"{info.points_count}"    )if __name__ == "__main__":    main()